using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Threading;using GlassBoard;
class AnimationTests {
static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(object o,string n){return o.GetType().GetField(n,F|BindingFlags.Public).GetValue(o);}static double D(object o,string n){return (double)Get(o,n);}static void Put(object o,string n,object v){o.GetType().GetField(n,F|BindingFlags.Public).SetValue(o,v);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);}
[STAThread]static int Main(){try{var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var source=new Window{Title="Animation test",Width=400,Height=250,Content=new TextBlock{Text="Live"}};source.Show();var windows=new List<RunningWindow>();for(int i=0;i<5;i++)windows.Add(new RunningWindow{Handle=new WindowInteropHelper(source).Handle,Title="Preview "+i});var pop=new ThumbnailPopup(windows,new Point(500,650),VisualTreeHelper.GetDpi(source).DpiScaleX);((DispatcherTimer)Get(pop,"pointerTimer")).Stop();var cards=(IList)Get(pop,"cards");
int cases=0;foreach(double width in new[]{360.0,640.0,1280.0,2560.0})foreach(double left in new[]{-1280.0,0.0}){var area=new Rect(left,0,width,800);Put(pop,"workArea",area);for(int hover=-1;hover<5;hover++){Call(pop,"SetHover",hover);double end=area.Left;foreach(var c in cards){double x=D(c,"TargetX"),w=D(c,"TargetW");if(x<area.Left||x+w>area.Right+.01||x<end-.01)throw new Exception("overlap or overflow");end=x+w;}cases++;}}Check(cases==48,"48 edge/width/hover layouts: no overlap or overflow");
Put(pop,"workArea",new Rect(0,0,1280,800));Call(pop,"SetHover",0);foreach(var c in cards){Put(c,"X",D(c,"TargetX"));Put(c,"Y",D(c,"TargetY"));Put(c,"W",D(c,"TargetW"));Put(c,"H",D(c,"TargetH"));}var c0=cards[0];double px=D(c0,"X")+20,py=D(c0,"Y")+40;Call(pop,"UpdatePointer",px,py,0.0);Call(pop,"UpdatePointer",px,py,100.0);Put(c0,"X",D(c0,"X")+100);for(int i=0;i<100;i++)Call(pop,"UpdatePointer",px,py,200.0+i*32);Check((int)Get(pop,"hovered")==0,"stationary pointer cannot retrigger hover as card geometry moves");Call(pop,"SetHover",-1);Put(pop,"animStart",-10000.0);Call(pop,"OnFrame",null,EventArgs.Empty);Check(!(bool)Get(pop,"animating")&&!(bool)Get(pop,"frameHooked"),"render subscription stops at animation completion");pop.Dispose();Check(!((DispatcherTimer)Get(pop,"pointerTimer")).IsEnabled,"pointer timer disposed");source.Close();Console.WriteLine("ALL PASS");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
